//! Source coordinates are pinned to CV1 raw bytes, never regenerated by trig.
#[derive(Clone)]
pub struct Case {
    pub name: String,
    pub n: usize,
    pub phase: &'static str,
    pub geometry: &'static str,
    pub source_sha256: &'static str,
    pub origin: [f64; 2],
    pub vertices: Vec<[f64; 2]>,
}
pub fn cases() -> Vec<Case> {
    let rect = [
        [0x3fc5c28f5c28f5c3, 0x3fcd70a3d70a3d71],
        [0x3fea8f5c28f5c28f, 0x3fcd70a3d70a3d71],
        [0x3fea8f5c28f5c28f, 0x3fe947ae147ae148],
        [0x3fc5c28f5c28f5c3, 0x3fe947ae147ae148],
    ];
    let square = [
        [0x3fdbfe86b0ab8be6, 0x3fd2ab30509fa4da],
        [0x3fe72d7a4647bae3, 0x3fd848410ee0cb62],
        [0x3fe45ef1e727279f, 0x3fe5525775625aa1],
        [0x3fd66175f26a655e, 0x3fe283cf1641c75d],
    ];
    let mut out = Vec::new();
    for (geometry, bits, hash, phases) in [
        (
            "rectangle",
            rect,
            "860b4140b7483797842e6c6bdeb1e661d1e8510fb0855cf9a69b772914208666",
            1,
        ),
        (
            "square-17",
            square,
            "2a2938a1ae4b12bfcc6c33ff3cb8fc332fc55436e1247c32638e8b83fde1b6cc",
            2,
        ),
    ] {
        for phase in 0..phases {
            for n in [4, 8, 16] {
                let phase_name = if phase == 0 { "origin" } else { "quarter" };
                out.push(Case {
                    name: format!("{geometry}-{phase_name}-n{n}"),
                    n,
                    phase: phase_name,
                    geometry,
                    source_sha256: hash,
                    origin: [if phase == 0 { 0.0 } else { 0.25 / n as f64 }; 2],
                    vertices: bits.map(|p| p.map(f64::from_bits)).to_vec(),
                });
            }
        }
    }
    out
}
